Given an unsorted array, find the minimum difference between any pair in the given array.Examples :Input: [1, 5, 3, 19, 18, 25]Output: 1Explanation: Minimum difference is between 18 and 19Input: [30, 5, 20, 9]Output: 4Explanation: Minimum difference is between 5 and 9Input: [1, 19, -4, 31, 38, 25, 100]Output: 5Explanation: Minimum difference is between 1 and -4Try It YourselfTable of Content[Naive Approach] Using Nested Loops – O(n²) Time and O(1) Space[Efficient Approach] Using Sorting – O(n log n) Time and O(1) Space[Naive Approach] Using Nested Loops – O(n²) Time and O(1) SpaceThe idea is to compare every possible pair of elements in the array and calculate their absolute differenceand keep track of the minimum diff. Initialize the minimum difference as infinity  Use two nested loops to generate all possible pairs  Compute absolute difference for each pair and update minimum value  Return the smallest difference obtained after all comparisons
            C++

    #include <iostream>
#include <vector>
#include <climits>
#include <cmath>

using namespace std;

// Returns minimum difference between any pair
int minDiff(vector<int>& arr)
{
    int n = arr.size();

    // Initialize difference as infinite
    int diff = INT_MAX;

    // Find the min diff by comparing difference
    // of all possible pairs in given array
    for (int i = 0; i < n - 1; i++)
    {
        for (int j = i + 1; j < n; j++)
        {
            if (abs(arr[i] - arr[j]) < diff)
                diff = abs(arr[i] - arr[j]);
        }
    }

    // Return min diff
    return diff;
}

// Driver code
int main()
{
    vector<int> arr = {1, 5, 3, 19, 18, 25};

    // Function call
    cout << minDiff(arr);

    return 0;
}


